@log_as_robot_keyword
def get_path_to_init():
    """    Function is taking proper path to init file.
    :return str: Path to __init__.py file.
    """
    init_dir = get_testline_configuration_directory_path()
    return os.path.join(init_dir, '__init__.py')


@log_as_robot_keyword
def get_selected_build(sw_name):
    build_tag = get_builtin_value('ENB_BUILD')
    selected_build = get_cm_source_build()
    if not selected_build:
        selected_build = get_builtin_value('SOURCE_SW')
    if not selected_build:
        selected_build = build_tag
    if not selected_build:
        selected_build = sw_name

    return selected_build


@log_as_robot_keyword
def get_scf_path(sw_name):
    """    Function is taking proper path to SCF file.
    :param str sw_name: Software version.
    :return str: Path to SCF file (.xml) file.
    """
    dfl = DefaultFileLocation()
    trunk_dirs = ['SBTS00', 'TRUNK']
    selected_build = get_selected_build(sw_name)
    build = SwVersionFactory.create_sw_version(selected_build)
    branch = [build.release]
    if build.is_trunk_build():
        branch.insert(0, build.get_release(use_default_for_trunk=False))
    scf_dir = dfl.get_commissioning_dir(branch=branch)
    tl_scf_dir = os.path.abspath(os.path.join(scf_dir, '..'))
    list_of_directories = os.listdir(tl_scf_dir)
    logging.debug(f'Available directories under {tl_scf_dir}: {list_of_directories}')
    logging.info(f'SCF dir: {scf_dir}')

    if os.path.exists(scf_dir):
        return scf_dir
    else:
        logging.debug(f'{scf_dir} not exists')
        logging.debug('Looking SCF from other releases...')
        sw_release = build.release
        logging.debug(f'Current SW VERSION: {selected_build}, RELEASE: {sw_release}')
        trunk_dir = [trunk_dir for trunk_dir in trunk_dirs if trunk_dir in list_of_directories]
        list_of_directories.append(sw_release)
        sorted_dir = sorted([_dir for _dir in list_of_directories if _dir not in trunk_dirs])
        dir_index = sorted_dir.index(sw_release)
        first_defined_release_back = sorted_dir[dir_index - 1] if dir_index > 0 else None
        logging.debug(f'First defined Release Back: {first_defined_release_back}')
        selected_dir = first_defined_release_back if first_defined_release_back else trunk_dir[0]
        logging.debug(f'Selected directory: {selected_dir}')
        if selected_dir:
            new_scf_path = os.path.join(tl_scf_dir, selected_dir)
            msg = (f'The directory {scf_dir} does not exists. '
                   f'To avoid blocking execution, it will try to use {new_scf_path} instead.')
            logging.warning(msg)
            if first_defined_release_back is None:
                msg = msg + '\nPlease create proper directory ASAP! '
                send_email_with_default_template(
                    subject='[Action Required] SCF does not exists',
                    additional_info=msg,
                    add_team_email=False)
            return new_scf_path

        doc_link = ("https://confluence.ext.net.nokia.com/display/5GPzKRK/"
                    "BTS+Commissioning+during+Test+Line+preparation")
        raise Exception(f'SCF dir {scf_dir} does not exist. Please check documentation: {doc_link}')


@log_as_robot_keyword
def get_node_scf_path(node_name, branch_scf_path, bts_type='GNB', bts_id=0, sub_device=None, scf_prefix_tag=None):
    """    Function to get proper SCF file.
    :param str node_name: Phrase to find proper SCF file in SCF locations,
    :param str branch_scf_path: Path to SCF file,
    :param str bts_type: GNB/ENB - added to support KRK scf name convention
    :param int bts_id: BTS id - related to Test Line configuration. - added to support KRK scf name convention
    :param str sub_device: eg ASIR
    :param str scf_prefix_tag: scf prefix tag - to indicate specific SCF eg: scf_prefix_tag=4CC --> 4CC_GNB0_SCF.xml
    :return: None.
    """
    dfl = DefaultFileLocation()
    scf_name = dfl.get_default_scf_name(bts_type, bts_id, sub_device=sub_device, prefix_tag=scf_prefix_tag)
    scf_path = os.path.join(branch_scf_path, scf_name)
    if os.path.isfile(scf_path):
        return scf_path
    scf_path = [branch_scf_path + '/' + file for file in os.listdir(branch_scf_path) if re.search(node_name, file)]
    if len(scf_path) == 1:
        return re.sub(r'//', r'/', scf_path[0])
    elif len(scf_path) > 1:
        raise FileNotFoundError(
            'In location {} is more than one SCF file which name meets the requirements'.format(branch_scf_path)
        )
    else:
        raise FileNotFoundError(
            'No SCF(for {}) found in location {}'.format(node_name, branch_scf_path)
        )


@log_as_robot_keyword
def get_neighbour_gnbs_and_enbs_info_defaults():

    def is_full_rack(bts_id, bts_type, du_id=0):
        cus = _get_airscale_object(bts=_get_bts_object(bts_id=bts_id, bts_type=bts_type), du_id=du_id).common_units
        return True if cus and len(cus) > 1 else False

    gnbs = [] if tl_config.tl.gnbs is None else tl_config.tl.gnbs
    enbs = [] if tl_config.tl.enbs is None else tl_config.tl.enbs
    main_bts = {}
    add_gnb = {}
    add_enb = {}

    main_bts_type = 'GNB' if gnbs else 'ENB'
    main_bts[f'{main_bts_type.lower()}_main'] = {
        'bts_id': 0, 'du_id': 0, 'is_main': True, 'bts_type': main_bts_type,
        'is_fullrack': is_full_rack(bts_id=0, bts_type=main_bts_type)
    }

    for gnb_id, gnb in enumerate(gnbs):
        if gnb_id > 0:
            add_gnb[f'gnb_{gnb_id}'] = {
                'bts_id': gnb_id, 'du_id': 0, 'is_main': False, 'bts_type': 'GNB',
                'is_fullrack': is_full_rack(bts_id=gnb_id, bts_type='GNB')}

    for enb_id, enb in enumerate(enbs):
        if main_bts_type == 'GNB':
            add_enb[f'enb_{enb_id}'] = {
                'bts_id': enb_id, 'du_id': 0, 'is_main': False, 'bts_type': 'ENB',
                'is_fullrack': is_full_rack(bts_id=enb_id, bts_type='ENB')}
        elif enb_id > 0:
            add_enb[f'enb_{enb_id}'] = {'bts_id': enb_id, 'du_id': 0, 'is_main': False, 'bts_type': 'ENB',
                                        'is_fullrack': is_full_rack(bts_id=enb_id, bts_type='ENB')}

    logging.info(f'main bts: {main_bts}')
    logging.info(f'enbs: {add_enb}')
    logging.info(f'gnbs: {add_gnb}')

    return main_bts, add_enb, add_gnb


@log_as_robot_keyword
def power_on_all_pdu_ports():
    tl = get_builtin_value(param_name='tl')

    def _send_email(failed):
        msg = ("There is a problem with one of the PDU devices. Please check the details in the logs.<br>"
               "If it is a connectivity issue, please raise a ticket with the COSI team.")
        for sf in failed:
            base_msg = f"Power on failed for BTS{sf['bts_id']} DU{sf['du_id']}"
            if 'ru_id' in sf:
                base_msg += f" RU{sf['ru_id']}"
            base_msg += f" Error: {repr(sf['error'])}"
            msg += f"<br><pre>{base_msg}</pre>"
        send_email_with_default_template(
            subject='[Action Required] PDU Power On Failed',
            additional_info=msg)

    def _try_to_power_on_pdu_port(obj, bts_id, du_id, ru_id=None):
        base_msg = "Power on failed for BTS{} DU{}".format(bts_id, du_id)
        try:
            if ru_id is not None:
                obj.radio_unit_power_on(bts_id=bts_id, du_id=du_id, radio_unit_id=ru_id, check_status_before=True)
                base_msg += " RU{}".format(ru_id)
            else:
                obj.bts_power_on(bts_id=bts_id, du_id=du_id, check_status_before=True)
        except Exception as e:
            log_info_to_console("{} due to {}".format(base_msg, repr(e)))
            logging.debug(traceback.format_exc())
            failed_params = {'object': obj, 'bts_id': bts_id, 'du_id': du_id, 'error': e}
            if ru_id is not None:
                failed_params['ru_id'] = ru_id
            return failed_params

    def _power_on_all_pdu_ports_for_bts(bts_type):
        if bts_type == 'ENB':
            btss = tl.enbs
            bts_du_operations = EnbDuOperations()
            bts_ru_operations = EnbRuOperations()
        else:
            btss = tl.gnbs
            bts_du_operations = GnbDuOperations()
            bts_ru_operations = GnbRuOperations()
        failed_power_on = []
        if btss:
            for bts_id, bts in enumerate(btss, 0):
                number_of_dues = len(bts.dus) if hasattr(bts, 'dus') else 1
                for du_id in range(number_of_dues):
                    if tl_config.get_bts_pdu_port(bts_id=bts_id, du_id=du_id, bts_type=bts_type):
                        ret = _try_to_power_on_pdu_port(bts_du_operations, bts_id, du_id)
                        if ret:
                            failed_power_on.append(ret)
                    rus = tl_config._get_rus(bts=bts, du_id=du_id, bts_type=bts_type)
                    if rus:
                        for ru_id, ru in enumerate(rus, 0):
                            if ru.pdu_port:
                                ret = _try_to_power_on_pdu_port(bts_ru_operations, bts_id, du_id, ru_id)
                                if ret:
                                    failed_power_on.append(ret)
        return failed_power_on

    failed_gnb = _power_on_all_pdu_ports_for_bts(bts_type='GNB')
    failed_enb = _power_on_all_pdu_ports_for_bts(bts_type='ENB')
    all_failed = failed_gnb + failed_enb
    if all_failed:
        _send_email(all_failed)
        max_attempts = 10
        interval = 30
        attempt = 2
        while attempt <= max_attempts:
            logging.debug(f"Attempt {attempt} to power on PDU")
            new_all_failed = []
            for single_fail in all_failed:
                results = _try_to_power_on_pdu_port(
                    single_fail['object'],
                    single_fail['bts_id'],
                    single_fail['du_id'],
                    single_fail.get('ru_id'))
                if results:
                    new_all_failed.append(results)
            if not new_all_failed:
                break
            else:
                all_failed = copy.copy(new_all_failed)
                attempt += 1
            time.sleep(interval)
        else:
            raise Exception(f"Cannot power on PDU after {max_attempts} attempts. "
                            f"Please check the logs for the details")


@log_as_robot_keyword
def is_asir_configuration(scf_path):
    with open(scf_path, "r") as scf_file:
        scf_content = scf_file.read()
        featcadm_params = get_all_params_under_class_name(scf_content, "com.nokia.srbts.mnl:FEATCADM")
        actasi = featcadm_params[0]['params'].get('actAsi')
        if actasi and actasi == "true":
            logging.debug("ASIR is enabled - checking radioMasterDN")
            asirmod_params = get_all_params_under_class_name(scf_content, "com.nokia.srbts.eqm:ASIRMOD")
            for record in asirmod_params:
                radio_dn = record['params'].get('radioMasterDN')
                if radio_dn is None or 'EXT' not in radio_dn:
                    logging.debug("radioMasterDN connected with local BTS, ASIR commissioning is required")
                    return True
            logging.debug("radioMasterDN connected with external BTS, Skipping ASIR commissioning")
        else:
            logging.debug("ASIR is disabled, Skipping ASIR commissioning")
        return False


@log_as_robot_keyword
def check_vm_and_restart_if_uptime_is_to_long(bts_id, du_id, bts_type):
    def _ping_vm(host):
        command = ['ping', '-c', '1', host]
        return subprocess.call(command) == 0

    vm_credentials = tl_config.get_bts_ws_credentials(bts_id=bts_id, du_id=du_id, bts_type=bts_type)
    ssh_conn.connect_to(hostname=vm_credentials['host'],
                        username=vm_credentials['user'],
                        password=vm_credentials['password'])
    uptime = datetime.strptime(ssh_conn.execute(command='uptime -s').strip(), '%Y-%m-%d %H:%M:%S')
    uptime_in_days = (datetime.now() - uptime).days
    if uptime_in_days >= 3:
        log_info_to_console("Neighbour VM should be rebooted because VM's uptime is longer than 3 days")
        ssh_conn.send_command(command='sudo reboot')
        ssh_conn.disconnect()
        time.sleep(30)
        try:
            time_to_reconnect_to_vm = 300
            while (not _ping_vm(vm_credentials['host'])) and (time_to_reconnect_to_vm > 0):
                time.sleep(1)
                time_to_reconnect_to_vm -= 1
        except Exception as err:
            raise ConnectFailedError(err)
        time.sleep(15)
        ssh_conn.connect_to(hostname=vm_credentials['host'],
                            username=vm_credentials['user'],
                            password=vm_credentials['password'])
        ssh_conn.disconnect()


@log_as_robot_keyword
def group_certificates(certificates):
    """    Groups certificates by their BTS type (GNB or ENB).
    This function organizes a list of certificate dictionaries into groups based on the value of a specified key.
    Each group is represented as a key-value pair in the resulting dictionary, where the key is the value of the
    specified grouping key, and the value is a list of certificates belonging to that group.

    :param list[dict] certificates: A list of dictionaries representing certificates.
    :param str group_by: The key used to group the certificates. Defaults to 'gnb'.
    :raises KeyError: If the specified grouping key is not found in any of the certificate dictionaries.
    :return tuple[dict or None, dict or None] : A tuple containing two dictionaries:
                                              - The first dictionary contains certificates grouped by the 'gnb' key.
                                              - The second dictionary contains certificates grouped by the 'enb' key.
                                              If no certificates are found for a specific group, the corresponding
                                              dictionary will be None.
    """
    def _group_certs_by_bts_type(certs, group_by):
        grouped_certs = dict()
        for cert in certs:
            c = cert.pop(group_by, None)
            if c is not None:
                if c not in grouped_certs:
                    grouped_certs[c] = []
                grouped_certs[c].append(cert)
                continue
        return grouped_certs or None

    gnb_certs = _group_certs_by_bts_type(certificates, 'gnb')
    enb_certs = _group_certs_by_bts_type(certificates, 'enb')
    return gnb_certs, enb_certs

@log_as_robot_keyword
def append_swconfig_flags_if_provided(source_swconfig_path, target_swconfig_path, flags=None):
    """
    Appends given flags to the content of swconfig.txt file if flags are provided
    without modifying the source file: writes result to a target file.

    When source_swconfig_path is None, only the flags (and comment) are written
    to the target file; no source content is read or written.

    :param source_swconfig_path: Path to the source swconfig.txt file, or None to write only flags.
    :param target_swconfig_path: Path to the target swconfig.txt file where result will be saved.
    :param flags: List of flags to append or a comma-separated string.
    :return: Path to the target swconfig.txt file with appended flags or source file if no flags are provided.
    """
    if isinstance(flags, str):
        flags = [flag.strip() for flag in flags.split(',')]
    elif flags is None:
        logging.debug(f"No flags provided, returning source file path: {source_swconfig_path}")
        return source_swconfig_path

    logging.debug(f"Additional swconfig flags to append: {flags}")

    content = None
    if source_swconfig_path is not None:
        with open(source_swconfig_path, 'r') as src_file:
            content = src_file.read()

    # Add flags (with comment that they were added by script)
    with open(target_swconfig_path, 'w') as tgt_file:
        if content is not None:
            tgt_file.write(content)
            tgt_file.write('\n')
        tgt_file.write('# The following flags were added automatically by the script.\n')
        for flag in flags:
            tgt_file.write(f'\n{flag}')

    logging.debug(f"Target swconfig.txt file with appended flags: {target_swconfig_path}")
    return target_swconfig_path
